<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('GET'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$sql=$id?'SELECT c.*, (SELECT COUNT(*) FROM coupon_usages u WHERE u.coupon_id=c.id) usage_count FROM coupons c WHERE c.id=:id':'SELECT c.*, (SELECT COUNT(*) FROM coupon_usages u WHERE u.coupon_id=c.id) usage_count FROM coupons c ORDER BY c.created_at DESC';$q=$db->prepare($sql);$q->execute($id?[':id'=>$id]:[]);$data=$id?$q->fetch():$q->fetchAll();if($id&&!$data)jsonResponse(false,'Coupon not found.',null,[],404);jsonResponse(true,'Coupons loaded.',$data);});
